"""31/10/2026: relatório rastreável a medições e capturas, sem escrever nos sítios."""
from pathlib import Path
import json,html,re,hashlib
O=Path(__file__).resolve().parents[1]
E=lambda x:html.escape(str(x).replace("·", "/").replace("—", ","))
def read(p):return json.loads((O/p).read_text(encoding='utf8'))
pages=read('paginas.json')
def table(head,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(path,label):return f'<a href="{path}">{E(label)}</a>'
def metric(p,w=390,t='light'):return read(f'medidas/{p["id"]}-{w}-{t}.json')
def changes(p,m):
 id=p['id'];h=m['height'];h1=m['h1'][0] if m['h1'] else None
 trio=[('Um título com função de cartaz',f'Título atual: {h1["size"]} px, {h1["font"]}.' if h1 else 'A lição usa a casca de leitura, sem h1 visível neste ecrã.','Bebas Neue de 39 a 61 px nos títulos-cartaz, entrelinha 1,05; Georgia 16/24,8 no texto. Preservar a casca durante a lição.'),('Uma peça de continuação','O aspeto da continuação varia entre famílias.','Região .cz-next, 24 px de espaço interno, título 25/30, ação .cz-button de altura mínima 48 px. Sem altura fixa quando a frase ocupa duas linhas.'),('Um percurso legível',f'Altura atual a 390 px: {h} px.','Linhas .cz-row de altura mínima 64 px, estado abaixo do título no telemóvel; portas dobradas de 88 px, abertas por âncora e pelo próximo passo.')]
 if id=='pt':trio=[('Recuperar uma entrada orientadora','A entrada mede 3816 px a 390 px; o estado aparece depois dos cartazes e dos convites.','Trazer uma região «A seguir» para a abertura, com seleção de módulo sem progresso e retoma com epi-ultima. Não substituir os destinos existentes.'),('Dar o mesmo estatuto aos três anos','Os três cartazes têm campos e contrastes diferentes; o terceiro é uma região escura extensa, visível na captura.','Três portas de papel com a mesma área acionável; a região de retoma é a figura dominante. Conservar imagens, identificação dos anos e ligações.'),('Desenhar as saídas como saídas','A ligação «Experimentar» mede 117,9 × 19 px.','Passar os convites autónomos para linhas de 64 px, sem sublinhado; o texto corrido conserva o sublinhado de 1 px.')]
 if id=='lente':trio=[('Orientar antes de enumerar',f'Entrada com {h} px no telemóvel.','Abertura com uma região de próximo passo e portas dobradas. A marca Lente conserva Arial: exceção explícita do sistema, não uma quarta família.'),('Separar destino e referência','Há ligações de crédito pequenas e ligações de navegação com sublinhado.','Cartão inteiro para o destino; crédito autónomo de 44 px e 13/19,5 px, a cinzento, com ↗ só para fora.'),('Unificar o rodapé','Saídas dispersas em texto no fim da captura.','Região de papel, saídas de 64 px numa grelha 4 × 1 / 2 × 2, alinhadas com a abertura.')]
 if id in ['lab','ver','treinar','criar']:
  trio=[('Transformar a ligação de secção numa porta','O rótulo publicado «Os seis percursos de Ver», substituído por «Observar» na decisão 54, tem alvo de 44 px, mas conserva o sublinhado de uma ligação no texto.' if id=='lab' else f'A página aberta mede {h} px a 390 px.','Cartão acionável completo, seta alinhada, sem sublinhado; listas dobradas em bandas de 88 px abaixo de 640 px. A lista completa continua no documento.'),('Fazer dos créditos uma tabela de museu','«Wikimedia Commons» mede 122,8 × 15 px nesta família.','Legenda adjacente à obra, 13/19,5 px; origem com alvo autónomo 44 px, sem sublinhado em repouso. Manter a imagem própria de cada página e a licença.'),('Dar à continuação a mesma estrutura','A ligação .continuar tem 58 px de altura na captura móvel e um contorno lateral vermelho.','Usar .cz-next e botão de 48 px mínimo; o vermelho fica no estado atual. Não duplicar a região com outro convite preto.')]
 if id=='percurso':trio=[('Retirar a repetição do vazio','Seis linhas exibem «POR FAZER»; cada linha mede 164,1 px a 390 px.','Não escrever estado sem registo; conservar «A seguir» e «Feita dd/mm», sem inventar datas. A linha cresce apenas com conteúdo real.'),('Unificar a retoma','A continuação mede 358 × 58 px e não usa a região invertida.','Mesma região de 24 px de espaço interno e botão de 48 px mínimo dos módulos.'),('Reforçar a continuidade','Título em Arial Black 32 px; linhas com número, texto e estado.','Título Bebas Neue; número, texto e seta em colunas estáveis; estado na segunda linha até 420 px.')]
 if id in ['peca','licao','sessao']:trio=[('Preservar a casca e melhorar a leitura','O botão «Seguinte» está em y=788, com 48 px de altura, no ecrã de 844 px.','Manter este alvo e a posição durante a leitura; limitar a prosa a 65 ch e 1,55 de entrelinha, sem mudar o motor nem as respostas.'),('Unificar o fecho, não acrescentar navegação','As famílias usam folhas de estilos e motores diferentes para os cartões.','Aplicar os mesmos tokens e a mesma peça «A seguir» no ecrã final; a barra comum só regressa no fim.'),('Crédito adjacente e fonte estável','O conteúdo é paginado; a capa não prova a qualidade de todos os cartões. A segunda captura de leitura está incluída.','A imagem e a sua tabela permanecem no mesmo cartão; «Ler a obra» ocupa posição constante no molde do Português. Auditar todos os cartões na fase 2.')]
 if id=='piloto':trio=[('Conservar o que já funciona','A região invertida já existe; as linhas medem 56 px e não escrevem o estado vazio.','Adotar o piloto como referência de comportamento. Subir o mínimo das linhas para 64 px apenas se a ronda aprovar a escala comum.'),('Afinar a hierarquia','Título Arial 38,4 px; ação inicial 358 × 81 px em duas linhas.','Título-cartaz Bebas Neue e botão com a mesma regra de 48 px mínimo. Evitar altura fixa de 48 px que corte o texto.'),('Desenhar a saída docente','A saída encontra-se no fim do módulo, fora de uma família de rodapé comum.','Rodapé de papel, alvo 64 px. Não alterar as sessões nem o calendário; o estudo é documental.')]
 if id=='cidadania':trio=[('Dar entrada aos módulos',f'Página com {h} px e título Arial 32 px.','Título-cartaz e uma região de próximo encontro. Os nomes Humanos, Algoritmos e Dilemas são propostas alinhadas com o encargo mais recente.'),('Ligar crédito e imagem','Ligações de autor na captura móvel têm 19 px de altura.','Tabela de museu adjacente e origem com alvo autónomo 44 px, sem alterar créditos ou licenças.'),('Dar a mesma forma às portas','Módulos e saídas usam soluções de ligação diferentes.','Portas de papel, alvo integral, seta e estado explícito; sem alterar o conteúdo do piloto.')]
 if id=='biblioteca':trio=[('Abrir pelo texto, sem perder o caminho',f'Índice com {h} px a 390 px.','Agrupar os textos em portas dobradas e manter a recomendação numa região «A seguir». Não esconder a pesquisa ou as ligações existentes.'),('Corrigir a ligação de ajuda','«Os vídeos de ajuda» tem 15 px de altura.','Saída autónoma com alvo 44 px; não a apresentar como uma palavra no texto corrido.'),('Dar consistência às atribuições','Os cartões juntam género, autor, data e duração numa mesma cadeia.','Título da obra em itálico; autoria e data em linha de apoio; estado próprio; uma única ligação para o cartão inteiro.')]
 if id=='atlas':trio=[('Corrigir o contraste dos sinais de expansão','Oito sinais «+» têm 2,8:1 em escuro, nas cinco larguras e na prova de projeção.','Usar color:var(--tinta) no sinal de expansão, com pelo menos 3:1; manter o texto do país e o estado expandido.'),('Hierarquizar os dois caminhos','«Encontrar uma pessoa» e «Seguir uma pergunta» concorrem antes do mapa.','Uma região de orientação e uma ação secundária de contorno; preservar as duas entradas e o mapa.'),('Separar mapa e portas',f'Índice com {h} px a 390 px.','Portas com alvo integral e seta; fonte cartográfica adjacente; manter os avisos de autoria dos dados. A licença dos pontos OpenStreetMap exige validação própria antes de qualquer reutilização de imagem.')]
 if id=='exame':trio=[('Reintegrar a identidade Cartaz','Título em Fraunces Oficina 39,2 px; interface usa Plex.','Bebas Neue nos cartazes, Georgia na leitura, Arial na interface. Preservar estrutura, sessões, dossiê e critérios.'),('Dar dimensão aos controlos',f'A recolha inicial identifica {len(m["smallTargets"])} alvos abaixo de 44 px; separar ligações corridas de controlos na tabela abaixo.','Botões e filtros de 48 px mínimo, saídas autónomas de 44 px; foco de 3 px com afastamento 4 px.'),('Reduzir a extensão inicial',f'Índice com {h} px a 390 px.','Agrupar sessões em portas dobradas, com uma região de retoma. A meta de altura só pode ser verificada sobre o índice completo, não neste recorte.')]
 return trio

intro='''<p class="eyebrow">GPT3 / Direção de desenho / 31.10.2026</p><h1>O Cartaz,<br>com uma só voz.</h1><p class="lead">Auditoria dos dois sítios e biblioteca de peças para uma decisão conjunta do docente e da direção de arte.</p><div class="status">FASE 1 / PROPOSTA / NÃO FUNDIR</div><p>O trabalho identifica diferenças de forma e comportamento, mede-as e propõe peças partilhadas. Não altera a barra comum, os geradores, os testes, as páginas publicadas ou as chaves de progresso. A fase 2 depende da decisão desta ronda.</p><p><strong>Leitura recomendada:</strong> decisões, quadro das 24 páginas, três mudanças por página e biblioteca visual. Cada medida liga à sua captura e ao registo de recolha.</p>'''
intro+='<aside class="decision54"><h2>Decisão 54: Observar</h2><p><strong>Já decidido pelo docente, comunicado em 01/11/2026:</strong> a primeira porta chama-se <strong>Observar</strong>. A sequência é <strong>Observar, Treinar, Criar</strong>. Esta decisão não volta a aprovação em D1 a D6.</p><p>As propostas, a biblioteca e os títulos desta auditoria usam Observar. As capturas e as medidas de base conservam o rótulo Ver que ainda estava publicado, como prova histórica.</p><p>A equipa da barra comum aplica os rótulos visíveis na entrada do Laboratório, na porta da entrada do Lente, nos percursos («Observar 1…»), no mapa e em «Ideias». O Caderno já usa Observar. Mantêm-se <code>narrativas/ver/</code>, as âncoras, os identificadores e todas as chaves de progresso. Este ramo continua apenas documental.</p></aside>'
decisions=[['D1','Aprovar a gramática das ligações','Sublinhado apenas na leitura; cartões sem sublinhado, créditos discretos e origem externa com ↗. Alvos autónomos de 44 px ou mais.','Aprovar / ajustar'],['D2','Aprovar a retoma comum','Uma região invertida, ação principal de 48 px mínimo e estado explícito. A exceção ao teste de grandes blocos pretos terá de ser decidida, não desligada.','Aprovar / contorno nas páginas abrangidas'],['D3','Aprovar a escala de 8 px','8, 16, 24, 32, 40, 48 e 64 px. O intervalo de 20 px do sistema de 24/10 passa a 24 px apenas nas famílias migradas.','Aprovar / conservar 20 px'],['D4','Aprovar os estados','Sem texto no estado vazio; «A seguir»; «Feita dd/mm». Um registo legado sem data diz só «Feita». Visitar uma ligação nunca marca conclusão.','Aprovar / ajustar'],['D5','Aprovar as dobras móveis','Bandas de 88 px; abertura por próximo passo e âncora; tudo acessível sem JavaScript, em impressão e projeção.','Aprovar / ajustar'],['D6','Fechar as exceções de identidade','Marca Lente em Arial permitida pelo sistema. Exame regressa às três famílias. Não introduzir terracota nova nem imagens novas nesta ronda.','Aprovar / especificar exceções']]
method='''<h2 id="metodo">Âmbito e método</h2><p>24 URLs escolhidos pelo encargo, sem dados de tráfego disponíveis. «Mais vistas» significa aqui a lista indicada pelo docente, não uma ordenação estatística. O Português foi congelado em <code>203eaf5dfbfb0cf9af921bb3a3691a354954d8cd</code>; o Lente em <code>03ef7728e47c615b62016e86a7b1dd9ef6a1fc22</code>. As capturas são renderizações locais destas versões, com os caminhos /pt/ e /lente/ preservados. A verificação do HTML público está em <a href="provas/publicacao.json">publicacao.json</a>; os 24 documentos HTML coincidem após normalizar os finais de linha CRLF/LF. A igualdade do HTML não certifica recursos externos.</p><p>Chromium 156, Windows, escala 1, locale pt-PT, Europe/London, contexto descartável por caso, sem progresso pessoal. Larguras 320, 390, 1024, 1366 e 1440 px; alturas 844 px nas duas larguras móveis e 900 px nas restantes. São 240 casos de base; as capturas a 390 e 1366 são integrais. Os restantes tamanhos têm capturas do primeiro ecrã e medidas da página inteira. Fontes aguardadas antes da captura; erros e pedidos falhados constam do JSON. A comparação principal usa 390 e 1366, claro e escuro.</p><p><strong>O que uma medida prova:</strong> retângulos em CSS px; altura do documento; transbordo; tipografia calculada; alvo real de cada ligação. O contraste é calculado por luminância sRGB em texto sobre fundos opacos sólidos. Fundos com imagem, transparência e opacidade não são certificados por este método. O ponto decorativo da marca Lente aparece na deteção automática e foi excluído da lista de bloqueios de leitura. Os sinais de expansão do Atlas não são decorativos.</p><p><strong>Limites:</strong> não é uma certificação WCAG completa. A revisão dos estados de uma lição inclui abertura e um cartão seguinte, não todas as respostas. A projeção foi ensaiada com ?projetar=1 e a sua ativação consta das classes medidas; a simples presença do parâmetro não prova suporte da página. A legibilidade no projetor físico e a revisão integral das licenças anteriores permanecem verificações de publicação. Nenhuma imagem foi produzida com IA. As imagens dos estudos provêm dos próprios sítios, com o crédito e a licença indicados.</p><p><strong>Antes e depois:</strong> o «antes» é integral. O «depois» é um estudo parcial de composição das três mudanças, sem o motor nem o conteúdo integral. A sua altura não é apresentada como redução comprovada da página. Os textos de demonstração são identificados. O espaço de ensaio da barra não é uma variante da barra comum nem define a sua altura final.</p>'''
overview=[];sections=[];markdown=['# Auditoria Cartaz, 31/10/2026', '**Decisão 54, comunicada em 01/11: Observar, Treinar, Criar.** As propostas usam Observar; as capturas mantêm Ver como prova histórica. A equipa da barra comum aplica os rótulos na entrada do Laboratório, na porta do Lente, nos percursos Observar 1…, no mapa e em Ideias. O Caderno já usa Observar. Mantêm-se narrativas/ver/, as âncoras e o progresso. Não se volta a pedir aprovação desta decisão.','Fase 1. Proposta documental. Não fundir.','[Abrir relatório HTML](relatorio.html) | [Biblioteca de peças](proposta/biblioteca.html) | [Tokens propostos](proposta/appearance.css)','']
for p in pages:
 m=metric(p);cases=[metric(p,w,t) for w in [390,1366] for t in ['light','dark']]
 trio=changes(p,m)
 primary=next((a for a in m['links'] if re.match('Começar|Continuar|Seguinte',a['text'])),None)
 overview.append([f'<a href="#{p["id"]}">{E(p["title"])}</a>',str(m['height']),str(metric(p,1366)['height']),str(max(c['overflow'] for c in cases)),str(len(m['smallTargets'])),f'{primary["y"]} / {primary["h"]}' if primary else 'Sem rótulo Começar / Continuar / Seguinte'])
 measurements=[]
 for c in cases:
  j=c['page'];key=f'{j["id"]}-{j["w"]}-{j["theme"]}';pri=next((a for a in c['links'] if re.match('Começar|Continuar|Seguinte',a['text'])),None)
  measurements.append([f'{j["w"]} / {"claro" if j["theme"]=="light" else "escuro"}',str(c['height']),str(c['overflow']),str(len(c['smallTargets'])),f'y={pri["y"]}, h={pri["h"]}' if pri else 'Não identificado por este rótulo',link(f'medidas/{key}.json','JSON')+' / '+link(f'capturas/{key}.jpg','captura')])
 findings=[]
 for title,before,after in trio:findings.append(['390 px / claro e escuro',E(before),'Semelhança / hierarquia / proximidade','Importante',E(after),link(f'capturas/{p["id"]}-390-light.jpg','captura integral')])
 seen=set()
 for c in cases:
  for a in c['smallTargets']:
   if a['text'] in seen or a['y']<0 or any(s in a['selector'] for s in ['projection','appearance']):continue
   seen.add(a['text']);inline=a['inline'];findings.append([f'{c["page"]["w"]} px / {c["page"]["theme"]}',f'{E(a["text"] or a["selector"])}: {a["w"]} × {a["h"]} px.','Dimensão do alvo / proximidade','Verificar contexto' if inline else 'Bloqueante',f'<code>{E(a["selector"])}</code>: '+('Se ligação corrida, conservar sublinhado; se origem ou saída autónoma, separar e aplicar min-height:44px; min-width:44px.' if inline else 'min-height:48px; min-width:48px; padding:8px 16px; sem altura fixa.'),link(f'medidas/{p["id"]}-{c["page"]["w"]}-{c["page"]["theme"]}.json','medida')])
   if len(seen)>=5:break
  if len(seen)>=5:break
 small=m['smallText']
 if small:findings.append(['390 px / claro',f'{len(small)} elementos com texto abaixo de 13 px; mínimo {min(x["size"] for x in small):g} px.','Legibilidade','Importante','Elevar os rótulos relevantes a 13/19,5 px; verificar o texto ampliado e a quebra antes de aplicar.',link(f'medidas/{p["id"]}-390-light.json','inventário')])
 if p['id']=='atlas':findings.insert(0,['320 a 1440 px / escuro','Oito sinais de expansão a 2,8:1, cor rgb(163,71,46).','Contraste de interface, mínimo 3:1','Bloqueante','.atlas-country-list summary b { color:var(--tinta) }. Não alterar todos os elementos b da página.',link('provas/atlas-contraste.png','captura localizada')+' / '+link('medidas/atlas-390-dark.json','medida')])
 if p['id']=='lente':findings.append(['Cinco larguras / ambos os temas','O ponto da marca entra na deteção automática de contraste baixo.','Figura e fundo','Pormenor, decorativo','Não confundir a marca com um indicador de conclusão. Conservar informação de progresso em palavra e símbolo.',link('medidas/lente-390-light.json','medida')])
 after=[]
 for w in [390,1366]:
  for t in ['light','dark']:
   key=f'{p["id"]}-{w}-{t}'
   after.append(f'<details><summary>{w} px / {"claro" if t=="light" else "escuro"}: antes e estudo depois</summary><div class="compare"><figure><a href="capturas/{key}.jpg"><img loading="lazy" src="capturas/{key}.jpg" alt="Antes: {E(p["title"])}"></a><figcaption>ANTES / página integral</figcaption></figure><figure><a href="capturas/depois-{key}.jpg"><img loading="lazy" src="capturas/depois-{key}.jpg" alt="Estudo depois: {E(p["title"])}"></a><figcaption>DEPOIS / recorte proposto, não implementado</figcaption></figure></div></details>')
 proj=link(f'capturas/projecao-{p["id"]}-light.jpg','projeção clara')+' / '+link(f'capturas/projecao-{p["id"]}-dark.jpg','projeção escura')
 if p['id'] in ['peca','licao','sessao']:proj+=' / '+link(f'capturas/leitura-{p["id"]}-light.jpg','cartão seguinte claro')+' / '+link(f'capturas/leitura-{p["id"]}-dark.jpg','cartão seguinte escuro')
 section=f'<section class="page" id="{p["id"]}"><p class="eyebrow">{E(p["url"])}</p><h2>{E(p["title"])}</h2><p>{link("https://pedrohfernandes-klk.github.io"+p["url"],"Página pública")} / {proj}</p>'+table(['Caso','Altura px','Transbordo px','Alvos <44','Ação identificada, px','Prova'],measurements)+table(['Onde','Problema','Princípio','Gravidade','Correção exata proposta','Prova'],findings)+'<h3>As três mudanças que mais elevam esta página</h3><ol>'+''.join(f'<li><strong>{E(a)}.</strong> {E(c)}</li>' for a,b,c in trio)+'</ol>'+''.join(after)+f'<p>{link("proposta/paginas/"+p["id"]+".html","Abrir estudo de composição")}</p></section>'
 sections.append(section)
 markdown+=['## '+p['title'],'Página: `'+p['url']+'`','','| Onde | Problema | Princípio | Gravidade | Correção | Prova |','|---|---|---|---|---|---|']
 for r in findings:markdown.append('| '+' | '.join(re.sub('<[^>]+>','',str(x)).replace('|','/') for x in r)+' |')
 markdown+=['','### Três mudanças']+[f'{i+1}. **{a}.** {c}' for i,(a,b,c) in enumerate(trio)]+['',f'[Claro, 390](capturas/{p["id"]}-390-light.jpg) · [Escuro, 390](capturas/{p["id"]}-390-dark.jpg) · [Claro, 1366](capturas/{p["id"]}-1366-light.jpg) · [Escuro, 1366](capturas/{p["id"]}-1366-dark.jpg)',f'[Estudo depois](proposta/paginas/{p["id"]}.html)','']

library='<h2 id="pecas">Biblioteca de peças</h2><p>Doze peças, medidas e estados aplicáveis. As pranchas de estado não são páginas de produto: repetem variantes para comparação. Os componentes informativos não inventam estados de interação.</p><p>'+link('proposta/biblioteca.html','Abrir a biblioteca')+' / '+link('proposta/biblioteca.html?tema=escuro','Abrir em escuro')+' / '+link('proposta/appearance.css','CSS proposto, sem aplicação')+'</p>'
labels=['Ligações na leitura','Cartões e listas','Créditos e fontes','Botões e Continuar','Portas','Percurso e progresso','Região A seguir','Migalhas','Tabela de museu','Citações e excertos','Avisos','Rodapé']
